const payload = $('Execute Workflow Trigger').item.json || {};
const args = payload.payload?.args || payload.args || {};
const msg = payload.message || payload.body?.message || payload || {};

const chatId = String(payload.chatId || msg.chat?.id || '').trim();
const rawText = String(msg.text || payload.text || payload.query || '').trim();

let location = String(args.location || '').trim();
if (!location) {
  location = rawText
    .replace(/^(thoi tiet|thời tiết|weather|nhiet do|nhiệt độ|troi|trời|du bao thoi tiet|dự báo thời tiết)\s*/i, '')
    .replace(/^(tai|tại|o|ở|cho|cho toi|cho tôi|hom nay|hôm nay)\s*/i, '')
    .trim();
}

if (!location) location = 'Ho Chi Minh City';

return [{ json: { chatId, rawText, location } }];

const source = $('Chuẩn Bị Địa Điểm').item.json || {};
const raw = $json?.data ?? $json;
const data = typeof raw === 'string' ? JSON.parse(raw) : (raw || {});

const current = Array.isArray(data.current_condition) ? data.current_condition[0] || {} : {};
const today = Array.isArray(data.weather) ? data.weather[0] || {} : {};
const desc = String(current.weatherDesc?.[0]?.value || '').trim();
const tempC = current.temp_C || '';
const feelsLike = current.FeelsLikeC || '';
const humidity = current.humidity || '';
const windKmph = current.windspeedKmph || '';
const maxTemp = today.maxtempC || '';
const minTemp = today.mintempC || '';
const rainMm = current.precipMM || '';

const translateDesc = (value = '') => {
  const key = String(value).trim().toLowerCase();
  const dict = {
    clear: 'quang mây',
    sunny: 'nắng đẹp',
    'partly cloudy': 'có mây nhẹ',
    cloudy: 'nhiều mây',
    overcast: 'âm u',
    mist: 'có sương mỏng',
    fog: 'có sương mù',
    haze: 'trời hơi mờ',
    rain: 'có mưa',
    'light rain': 'mưa nhẹ',
    'moderate rain': 'mưa vừa',
    'heavy rain': 'mưa to',
    thunderstorm: 'có dông',
  };
  return dict[key] || key;
};

const location = String(source.location || 'đó').trim();
const parts = [];

if (desc) {
  parts.push(`Hiện tại ở ${location}, trời ${translateDesc(desc)}.`);
} else {
  parts.push(`Hiện tại ở ${location}, Mia đã lấy được thông tin thời tiết mới nhất.`);
}

if (tempC !== '') {
  let line = `Nhiệt độ khoảng ${tempC}°C`;
  if (feelsLike !== '') line += `, cảm giác như ${feelsLike}°C`;
  parts.push(`${line}.`);
}

const details = [];
if (humidity !== '') details.push(`độ ẩm ${humidity}%`);
if (windKmph !== '') details.push(`gió ${windKmph} km/h`);
if (rainMm !== '' && rainMm !== '0.0') details.push(`mưa ${rainMm} mm`);
if (minTemp !== '' || maxTemp !== '') details.push(`trong ngày dao động từ ${minTemp || '?'}°C đến ${maxTemp || '?'}°C`);
if (details.length) parts.push(`Mia ghi nhận ${details.join(', ')}.`);

return [{ json: { chatId: source.chatId || '', text: parts.join(' ').trim() } }];

const source = $input.item.json || {};

function decodeEntities(value = '') {
  return String(value)
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'");
}

function htmlToPlainText(value = '') {
  return decodeEntities(String(value || ''))
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<li>/gi, '- ')
    .replace(/<\/h\d>/gi, '\n')
    .replace(/<a[^>]*href="([^"]+)"[^>]*>(.*?)<\/a>/gi, '$2 ($1)')
    .replace(/<[^>]+>/g, ' ')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n\s+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const rawText = String(
  source.text ||
  source.responseText ||
  source.output ||
  source.response ||
  ''
).trim();

const plainText = String(source.plainText || htmlToPlainText(rawText)).trim();

return [{
  json: {
    ...source,
    text: plainText || rawText
  }
}];
